{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The PICOS (Participants, Interventions, Comparisons, Outcomes, Study Designs) checklist was used to identify the inclusion criteria in this review. 17 Participants (P): This review included trials if they targeted persons with stroke (ischemic and hemorrhagic), regardless of comorbidities and any previous treatments, but excluded those with manic or psychotic episodes/symptoms in order to reduce biases associated with non-target symptoms. Participants were included whether or not they received pharmacological interventions (any dosage or duration) for depression or other illnesses. Interventions (I) and controls (C): This review considered trials that compared the effects of NPIs for post-stroke individuals with depressive symptoms (eg, music therapy, massage therapy, behavioral therapy, or physical exercise with any frequency, intensity, or duration) to control conditions, such as usual treatment. Outcomes (O): The primary outcome of this review was depressive symptoms, measured by any validated depression scale. Study designs (S): This review considered any RCT with a pre-post design, meaning that outcomes were measured at pre-intervention, post-intervention, and follow-up.",
      "reason": "The study explicitly specifies all PICOS components, including participants (stroke), interventions (NPIs), comparisons (control), outcomes (depressive symptoms), and study designs (RCT with pre-post/follow-up)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The search was restricted to randomized controlled trials (RCTs) written in English and published in peer-reviewed journals.",
      "reason": "The manuscript specifies language (English) and publication status (peer-reviewed journals). The dissemination year (January 2000 to August 2018) is specified in text_5."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript states 25 articles were excluded for not meeting inclusion criteria but does not explicitly distinguish between exclusion due to outcomes not being measured versus outcomes not being reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "These trials were grouped into four types: CAT (n = 5), exercise (n = 4), psychosocial therapy (n = 2), and multifactorial therapy (n = 2) (Table 2).",
      "reason": "The groups used in synthesis (CAT, exercise, psychosocial, multifactorial) are specified and linked to the NPI comparisons defined in the objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "Trials published between January 2000 and August 2018 were considered for inclusion; this date range reflects findings from an initial search in MEDLINE and CINAHL, which showed no relevant trials before 2000.",
      "reason": "A rationale is provided for the year restriction (reflects findings from an initial search). Additionally, text_6 provides a rationale for excluding participants with manic or psychotic episodes."
    }
  ],
  "confidence": 90
}

